/bin/bash -lc "node --input-type=module <<'JS'
import { readFileSync } from 'node:fs'
import assert from 'node:assert/strict'
const shell = readFileSync('.next/server/app/index.html', 'utf8')
for (const heading of ['<h1>Dashboard</h1>', '<h2>Total Revenue</h2>', '<h2>Total Invoices</h2>', '<h2>Revenue</h2>', '<h2>Latest Invoices</h2>']) {
  assert.ok(shell.includes(heading), "'`Missing static heading: ${heading}`)
}
for (const label of ['"'Loading total revenue...', 'Loading total invoices...', 'Loading revenue...', 'Loading latest invoices...']) {
  assert.ok(shell.includes(label), "'`Missing local fallback: ${label}`)
}
assert.ok(!shell.includes('"'Loading dashboard...'), 'Route fallback replaced the dashboard shell')
console.log('PASS: prerendered HTML contains the full dashboard structure and all four local fallbacks.')
JS"

/bin/bash -lc "node --input-type=module <<'JS'
import assert from 'node:assert/strict'
for (let request = 1; request <= 2; request++) {
  const started = performance.now()
  const response = await fetch('http://127.0.0.1:3100')
  assert.equal(response.status, 200)
  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let body = ''
  let shellTime
  let dataTime
  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    body += decoder.decode(value, { stream: true })
    if (shellTime === undefined && body.includes('Loading latest invoices...')) {
      shellTime = performance.now() - started
      for (const heading of ['<h1>Dashboard</h1>', '<h2>Total Revenue</h2>', '<h2>Total Invoices</h2>', '<h2>Revenue</h2>', '<h2>Latest Invoices</h2>']) {
        assert.ok(body.includes(heading), "'`Missing initial heading: ${heading}`)
      }
      assert.ok(!body.includes('"'PPR Test Customer'), 'API result arrived before shell check')
    }
    if (dataTime === undefined && body.includes('PPR Test Customer')) dataTime = performance.now() - started
  }
  assert.ok(shellTime "'!== undefined, '"'No dashboard shell streamed')
  assert.ok(dataTime "'!== undefined, '"'No invoice data streamed')
  assert.ok(dataTime - shellTime > 1000, 'Shell did not arrive ahead of slow data')
  for (const value of ['123,456', '42', 'September', '15,000', 'PPR Test Customer', '1,200']) {
    assert.ok(body.includes(value), "'`Missing rendered data: ${value}`)
  }
  assert.ok(!body.includes('"'data-dgst='), 'Unexpected server rendering error')
  console.log("'`PASS request ${request}: shell ${Math.round(shellTime)}ms, data ${Math.round(dataTime)}ms; all dashboard values streamed.`)
}
JS'
